import { existsSync, readFileSync } from 'fs';
import Joi from 'joi';
import yargs from 'yargs';

const argv = yargs.argv;
export const BASELINE_DEFAULT = 'veracode_baseline.json';
export const DISPOSITIONS_DEFAULT = 'veracode_dispositions.json';
export const CODEOWNERS_DEFAULT = 'CODEOWNERS';

export interface BaselineFile {
  findings: any[];
}

export interface DispositionsFile {
  dispositions: any[];
}

const dispositionSchema = Joi.object({
  disposition: Joi.string().required(),
  'disposition-owner': Joi.string()
    .regex(/.*@powerschool\.com$/)
    .required(),
  'disposition-comment': Joi.string().min(1).required(), // Just need to write something

  procedure_hash: Joi.string()
    .regex(/[0-9]+/)
    .required(),
  prototype_hash: Joi.string()
    .regex(/[0-9]+/)
    .required(),
  flaw_hash: Joi.string()
    .regex(/[0-9]+/)
    .required(),
  flaw_hash_count: Joi.number().required(),
  flaw_hash_ordinal: Joi.number().required(),
  cause_hash: Joi.string()
    .regex(/[0-9]+/)
    .required(),
  cause_hash_count: Joi.number().required(),
  cause_hash_ordinal: Joi.number().required(),
  cause_hash2: Joi.string()
    .regex(/[0-9]+/)
    .required(),
  cause_hash2_ordinal: Joi.string()
    .regex(/[0-9]+/)
    .required()
});

const findingSchema = Joi.object({
  title: Joi.string().required(),
  issue_id: Joi.number(),
  gob: Joi.string().required(),
  severity: Joi.number().required(),
  issue_type_id: Joi.string().required(),
  issue_type: Joi.string().required(),
  cwe_id: Joi.string().required(),
  display_text: Joi.string().required(),
  files: {
    source_file: {
      file: Joi.string().required(),
      line: Joi.number().required(),
      function_name: Joi.string().required(),
      qualified_function_name: Joi.string().required(),
      function_prototype: Joi.string().required(),
      scope: Joi.string().required()
    }
  },
  flaw_match: {
    procedure_hash: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    prototype_hash: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    flaw_hash: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    flaw_hash_count: Joi.number().required(),
    flaw_hash_ordinal: Joi.number().required(),
    cause_hash: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    cause_hash_count: Joi.number().required(),
    cause_hash_ordinal: Joi.number().required(),
    cause_hash2: Joi.string()
      .regex(/[0-9]+/)
      .required(),
    cause_hash2_ordinal: Joi.string()
      .regex(/[0-9]+/)
      .required()
  },
  flaw_details_link: Joi.string().uri().required()
});

export async function lintBaselineFile(
  filename: string
): Promise<BaselineFile> {
  if (!existsSync(filename)) {
    throw new Error(`baseline file ${filename} not found`);
  }

  const fileContent = JSON.parse(readFileSync(filename).toString());
  if (fileContent.findings == null) {
    throw new Error(`expected "findings" property in ${filename}`);
  }

  for (const finding of fileContent.findings) {
    // Validate each finding.
    const { error } = findingSchema.validate(finding);
    if (error) {
      throw new Error(error.message);
    }
  }

  return fileContent;
}

export async function lintDispositionsFile(
  dispositionsFileName: string
): Promise<DispositionsFile> {
  if (!existsSync(dispositionsFileName)) {
    throw new Error(`dispositions file ${dispositionsFileName} not found`);
  }
  const fileContent = JSON.parse(readFileSync(dispositionsFileName).toString());
  if (fileContent.dispositions == null) {
    throw new Error(
      `expected "dispositions" property in ${dispositionsFileName}`
    );
  }

  for (const disposition of fileContent.dispositions) {
    // Validate each resolution.
    const { error } = dispositionSchema.validate(disposition);
    if (error) {
      throw new Error(error.message);
    }
  }

  return fileContent;
}

/**
 * Lint the CODEOWNERS file. If it exists, it should basically be fixed and include all the necessary files.
 * @param codeownersFileName
 */
export async function lintCodeOwnersFile(
  codeownersFileName: string
): Promise<string> {
  if (!existsSync(codeownersFileName)) {
    throw new Error(`code owners file ${codeownersFileName} not found`);
  }
  const fileContent = readFileSync(codeownersFileName).toString();
  const ownersByFile: { [fileName: string]: string[] } = {};

  for (const line of fileContent.split(/\r?\n/).map((tLine) => tLine.trim())) {
    // Comments and empties allowed
    if (line.length === 0 || line.startsWith('#')) continue;

    // Else it's: filename @owner1 @owner2...
    const fields = line.split(/[ \t]+/).map((el) => el.trim());
    if (fields.length < 2) {
      throw new Error(
        `expected one or more owners in CODEOWNERS line: ${line}`
      );
    }

    ownersByFile[fields[0]] = fields.slice(1);
  }

  for (const f of [
    BASELINE_DEFAULT,
    DISPOSITIONS_DEFAULT,
    CODEOWNERS_DEFAULT
  ]) {
    if (ownersByFile[f] == null) {
      throw new Error(`expected ${f} in CODEOWNERS file`);
    }

    // They need to start with '@' signs
    if (ownersByFile[f].some((owner) => !owner.startsWith('@'))) {
      throw new Error(
        `code owner for ${f} in CODEOWNERS file should start with '@' sign`
      );
    }
  }

  return fileContent;
}

export interface FlawMatch {
  procedure_hash: string;
  flaw_hash: string;
  cause_hash: string;
  cause_hash2: string;
}

export function matches(
  disposition: FlawMatch,
  finding: { flaw_match: FlawMatch }
): boolean {
  return (
    disposition.procedure_hash === finding.flaw_match.procedure_hash &&
    disposition.flaw_hash === finding.flaw_match.flaw_hash &&
    disposition.cause_hash === finding.flaw_match.cause_hash &&
    disposition.cause_hash2 === finding.flaw_match.cause_hash2
  );
}

/**
 * Make sure all the dispositions are in the baseline, and vice versa.
 * @param dispositions dispositions file
 * @param baseline baseline file
 */
export function verifyDispositionsInBaseline(
  dispositions: DispositionsFile,
  baseline: BaselineFile
): void {
  const errors: string[] = [];
  for (const disposition of dispositions.dispositions) {
    let found = false;
    for (const finding of baseline.findings) {
      if (matches(disposition, finding)) {
        found = true;
        break;
      }
    }

    if (!found) {
      errors.push(
        `disposition not in findings: procedure_hash=${disposition.procedure_hash}, flaw_hash=${disposition.flaw_hash}, cause_hash=${disposition.cause_hash}, cause_hash2=${disposition.cause_hash2}`
      );
    }
  }

  for (const finding of baseline.findings) {
    let found = false;
    for (const disposition of dispositions.dispositions) {
      if (matches(disposition, finding)) {
        found = true;
        break;
      }
    }

    if (!found) {
      errors.push(
        `finding not in dispositions: procedure_hash=${finding.flaw_match.procedure_hash}, flaw_hash=${finding.flaw_match.flaw_hash}, cause_hash=${finding.flaw_match.cause_hash}, cause_hash2=${finding.flaw_match.cause_hash2}`
      );
    }
  }

  if (errors.length > 0) {
    throw new Error(errors.join('\n'));
  }
}

export async function main(
  args: { [key: string]: string | number },
  debug = false
): Promise<void> {
  const baselineFileName = (
    args.baseline ? args.baseline : BASELINE_DEFAULT
  ) as string;
  const dispositionsFileName = (
    args.dispositions ? args.dispositions : DISPOSITIONS_DEFAULT
  ) as string;
  const codeownersFileName = (
    args.codeowners ? args.codeowners : CODEOWNERS_DEFAULT
  ) as string;

  // If there's no baseline file, that's fine - no flaws, we're done.
  // Otherwise, we need both the baseline and code owners files.
  if (!existsSync(baselineFileName)) {
    if (debug)
      console.log(`no baseline file found ${baselineFileName}, exiting.`);
  } else {
    const baseline = await lintBaselineFile(baselineFileName);
    const dispositions = await lintDispositionsFile(dispositionsFileName);
    await lintCodeOwnersFile(codeownersFileName);

    verifyDispositionsInBaseline(dispositions, baseline);
  }
}

if (require.main === module) {
  (async () => {
    await main(argv as { [key: string]: string | number }, true);
  })().catch((e) => {
    console.error(e);
  });
}
